const ctxYT=(c,q)=>'https://www.youtube.com/results?search_query='+encodeURIComponent(c+' '+q);
/* the app's technique lessons, easiest first, spread across stages 1 to 7 */
function ctxLessons(inst,n){const t=techT(inst);const ks=Object.keys(t);if(!ks.length||n>7)return[];
 const s=ks.map((k,i)=>[k,techDiff(inst,k)??1,i]).sort((a,b)=>a[1]-b[1]||a[2]-b[2]);
 return s.filter((_,i)=>1+Math.floor(i*7/s.length)===n).map(([k])=>[k,t[k].name||k])}
function ctxDone(){return store.get('ctxdone',{})}
function techStepsHTML(n){const inst=cInst(),X=cData().stages[n],E=(CTX[inst]||{})[n]||[];if(!X||!X.tech||!E.length)return'';
 const dn=ctxDone(),got=E.filter((_,i)=>dn[inst+'-'+n+'-'+i]).length,L=ctxLessons(inst,n);
 const item=(e,i)=>{const id=inst+'-'+n+'-'+i,ok=!!dn[id];return`<details class="ctx${ok?' ok':''}" data-id="${id}"><summary><span class="ctxn" aria-hidden="true">${ok?'✓':i+1}</span><b>${esc(X.tech[i])}</b>${ok?'<span class="sr">(you can do this)</span>':''}</summary>
  <div class="ctxb"><div class="ctxg"><div><h4>How to do it</h4><p>${esc(e[0])}</p></div><div><h4>What it should feel like</h4><p>${esc(e[1])}</p></div><div><h4>The usual mistake</h4><p>${esc(e[2])}</p></div><div><h4>Check yourself</h4><p>${esc(e[3])}</p></div></div>
  <div class="row"><a class="btn small primary" href="${ctxYT(e[4],e[5])}" target="_blank" rel="noopener">▶ Watch on YouTube: ${esc(e[4])} ↗</a><button class="btn small ctxmark" aria-pressed="${ok}">${ok?'Ticked: I can do this':'I can do this'}</button></div></div></details>`};
 return`<section class="panel ctxp" id="ctx-${n}"><h3>Technique, step by step <span class="hint">${got} of ${E.length} ticked</span></h3>
 <p class="hint">Open each one to see what to do, how it should feel, the usual mistake and a video to watch. Tick it when you can do it comfortably.</p>
 <div class="ctxl">${E.map(item).join('')}</div>
 ${L.length?`<p class="ctxa"><b>Try it in the app:</b> ${L.map(([k,nm])=>`<a class="schip" href="#learn-tech-${inst}-${k}">${esc(nm)}</a>`).join(' ')}</p>`:''}</section>`}
function ctxBind(root,n){root.querySelectorAll('.ctxp .ctxmark').forEach(b=>b.onclick=()=>{const d=b.closest('.ctx'),id=d.dataset.id,dn=ctxDone();if(dn[id])delete dn[id];else dn[id]=Date.now();store.set('ctxdone',dn);
 const p=root.querySelector('.ctxp');const open=[...p.querySelectorAll('.ctx')].map(x=>x.open);p.outerHTML=techStepsHTML(n);const q=root.querySelector('.ctxp');q.querySelectorAll('.ctx').forEach((x,i)=>x.open=open[i]);ctxBind(root,n);const m=q.querySelector(`[data-id="${id}"] .ctxmark`);if(m)m.focus()})}
{const _vs=viewCourseStage;viewCourseStage=function(n){_vs(n);const put=()=>{if(location.hash!=='#course-'+n||main.querySelector('.ctxp'))return;const g=main.querySelector('.crsgoals');const h=techStepsHTML(n);if(g&&h){g.insertAdjacentHTML('afterend',h);ctxBind(main,n)}};put();const ob=new MutationObserver(()=>{if(location.hash!=='#course-'+n){ob.disconnect();return}put()});ob.observe(main,{childList:true})}}
